const pad = (n: number) => String(n).padStart(2, "0");

const Heading = ({
  children,
  id,
  level,
}: {
  children: ReactNode;
  id: string;
  level: 1 | 2;
}) =>
  level === 1 ? (
    <h1 className="sr-only" id={id}>
      {children}
    </h1>
  ) : (
    <h2 className="sr-only" id={id}>
      {children}
    </h2>
  );

/** A feature's name is a heading one level under the section's. */
const FeatureHeading = ({
  children,
  level,
}: {
  children: ReactNode;
  level: 2 | 3;
}) => (level === 2 ? <h2>{children}</h2> : <h3>{children}</h3>);

/**
 * One line of the index: number, name, and when active, its story. An
 * accordion where one panel is always open: the open line's button is
 * aria-disabled (it can't close), and closed panels are inert, so their
 * text and link are neither read nor focusable while folded away.
 */
const IndexLine = ({
  active,
  feature,
  headingLevel,
  index,
  linkLabel,
  onSelect,
  buttonRef,
}: {
  active: boolean;
  feature: SphereFeature;
  headingLevel: 2 | 3;
  index: number;
  linkLabel: string;
  onSelect: () => void;
  buttonRef: (node: HTMLButtonElement | null) => void;
}) => {
  const panelId = useId();
  return (
    <li className="border-border/60 relative border-t first:border-t-0">
      {/* The count, pinned to the row's top-right corner. It repeats the
          list's own order, so it's hidden from screen readers. */}
      <span
        aria-hidden
        className={cn(
          "pointer-events-none absolute top-2.5 right-0 font-mono text-[0.6875rem] tracking-[0.08em] tabular-nums transition-colors duration-[var(--index-duration)] motion-reduce:transition-none lg:top-3.5",
          active ? "text-foreground" : "text-muted-foreground"
        )}
      >
        {pad(index + 1)}
      </span>
      <FeatureHeading level={headingLevel}>
        <button
          ref={buttonRef}
          aria-controls={panelId}
          aria-disabled={active || undefined}
          aria-expanded={active}
          className="group/line focus-visible:outline-foreground flex w-full items-baseline py-1.5 pr-8 text-left outline-offset-4 focus-visible:outline-2 lg:py-2"
          onClick={onSelect}
          type="button"
        >
          <span
            className={cn(
              "text-[1.75rem] leading-[1.05] tracking-[-0.035em] [overflow-wrap:anywhere] transition-[color,font-weight] duration-[var(--index-duration)] ease-[var(--index-ease)] motion-reduce:transition-none sm:text-5xl lg:text-6xl xl:text-7xl",
              // Dimmed, but at 3:1 or more for large text in both themes.
              active
                ? "text-foreground font-semibold"
                : "text-muted-foreground/80 group-hover/line:text-muted-foreground font-light"
            )}
          >
            {feature.label}
          </span>
        </button>
      </FeatureHeading>

      {/* Unfolds under the active line, on the same left edge as the name. */}
      <div
        className={cn(
          "grid transition-[grid-template-rows,opacity] duration-[var(--index-duration)] ease-[var(--index-ease)] motion-reduce:transition-none",
          active ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0"
        )}
        id={panelId}
        inert={!active}
      >
        {/* Padded inside the clip, so the link's focus ring isn't cut off. */}
        <div className="-mx-1 overflow-hidden px-1">
          <div className="flex flex-col gap-3 pt-1 pb-4 sm:flex-row sm:items-end sm:justify-between sm:gap-6 lg:pb-5">
            <p className="text-muted-foreground max-w-[22rem] text-sm leading-relaxed text-pretty sm:text-[0.9375rem]">
              {feature.description}
            </p>
            {feature.href ? (
              <a
                className="text-foreground focus-visible:outline-foreground inline-flex min-h-6 shrink-0 items-center gap-1.5 font-mono text-[0.6875rem] tracking-[0.08em] uppercase underline-offset-4 hover:underline focus-visible:outline-2 focus-visible:outline-offset-2"
                href={feature.href}
              >
                {linkLabel}
                <span className="sr-only">: {feature.label}</span>
                <span aria-hidden>→</span>
              </a>
            ) : null}
          </div>
        </div>
      </div>
    </li>
  );
};

export const FeatureSphereSection = ({
  title = "What we do",
  features = DEFAULT_FEATURES,
  extraImages = DEFAULT_EXTRAS,
  linkLabel = "View work",
  defaultFeature,
  onFeatureChange,
  headingLevel = 2,
  sphereSide = "right",
  sphere,
  className,
  style,
  ...props
}: FeatureSphereSectionProps) => {
  const titleId = useId();
  const buttons = useRef<(HTMLButtonElement | null)[]>([]);
  const [active, setActive] = useState(() =>
    Math.max(
      features.findIndex((f) => f.id === defaultFeature),
      0
    )
  );

  const select = (index: number) => {
    if (index < 0 || index === active) {
      return;
    }
    setActive(index);
    onFeatureChange?.(features[index].id);
  };

  // Tab moves through the index like any list of buttons; the arrow keys
  // also step between features, and Home and End jump to the ends (the
  // accordion pattern's optional keys).
  const onIndexKeyDown = (event: KeyboardEvent<HTMLOListElement>) => {
    const from = buttons.current.indexOf(event.target as HTMLButtonElement);
    if (from === -1) {
      return;
    }
    const last = features.length - 1;
    const to = {
      ArrowDown: from === last ? 0 : from + 1,
      ArrowUp: from === 0 ? last : from - 1,
      End: last,
      Home: 0,
    }[event.key];
    if (to !== undefined) {
      event.preventDefault();
      buttons.current[to]?.focus();
    }
  };

  const sphereLeft = sphereSide === "left";

  // The sphere's items and groups, from the features.
  const groups: ImageSphereGroup[] = features.map((f) => ({
    id: f.id,
    label: f.label,
  }));
  const items: ImageSphereItem[] = [
    ...features.flatMap((f) =>
      f.images.map((image) => ({ ...image, group: f.id }))
    ),
    ...extraImages,
  ];

  return (
    // No fixed height: the index grows with its text (zoomed or enlarged
    // text is never clipped); the sphere has its own height.
    <section
      aria-labelledby={titleId}
      className={cn(
        "bg-background text-foreground grid lg:min-h-[48rem]",
        sphereLeft
          ? "lg:grid-cols-[minmax(0,1.1fr)_minmax(0,1fr)]"
          : "lg:grid-cols-[minmax(0,1fr)_minmax(0,1.1fr)]",
        className
      )}
      style={{ ...TRANSITION, ...style }}
      {...props}
    >
      <Heading id={titleId} level={headingLevel}>
        {title}
      </Heading>

      {/* The index. */}
      <div
        className={cn(
          "order-2 flex flex-col justify-center px-5 pt-2 pb-6 sm:px-8 lg:py-12",
          sphereLeft
            ? "lg:order-2 lg:pr-12 lg:pl-4 xl:pr-16"
            : "lg:order-1 lg:pr-4 lg:pl-12 xl:pl-16"
        )}
      >
        <ol onKeyDown={onIndexKeyDown}>
          {features.map((feature, k) => (
            <IndexLine
              key={feature.id}
              active={k === active}
              feature={feature}
              headingLevel={headingLevel === 1 ? 2 : 3}
              index={k}
              linkLabel={linkLabel}
              onSelect={() => select(k)}
              buttonRef={(node) => {
                buttons.current[k] = node;
              }}
            />
          ))}
        </ol>
      </div>

      {/* The sphere. */}
      <div
        className={cn(
          "relative order-1 h-[21rem] min-h-0 sm:h-[28rem] lg:h-auto",
          sphereLeft ? "lg:order-1" : "lg:order-2"
        )}
      >
        <ImageSphere
          aria-label="Images for each feature"
          hint={null}
          {...sphere}
          className={cn(
            "aspect-auto h-full sm:aspect-auto lg:aspect-auto",
            sphere?.className
          )}
          group={features[active]?.id ?? null}
          groups={groups}
          items={items}
          onGroupChange={(id) => {
            if (id) {
              select(features.findIndex((f) => f.id === id));
            }
          }}
        />
      </div>
    </section>
  );
};

export default FeatureSphereSection;

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type {
  ComponentProps,
  KeyboardEvent,
  ReactNode,
  RefObject,
} from "react";

import { cn } from "@/lib/utils";

import { createSphereRenderer } from "./image-sphere-gl";
import type { SphereRenderer } from "./image-sphere-gl";
import { CLUSTER_MAX, SphereScene } from "./image-sphere-scene";

/* ─────────────────────────────────────────────────────────────────────────
 * Image sphere. Your images on a globe you can hold, drawn with WebGL:
 * grab it and fling it, click an image and its group
 * gathers into a pile. Click empty space (or press Escape) to put it back.
 *
 *   image-sphere-scene.ts   the physics: where every card is, frame by frame
 *   image-sphere-gl.ts      draws them: one draw call, one texture atlas
 *   this file               props, input, and the HTML over the canvas: the
 *                           hover tag, group buttons for keyboards, and a
 *                           plain grid for browsers without WebGL2
 *
 * Images load straight into the GPU, so they must be same-origin or served
 * with CORS headers (Unsplash, Cloudinary, imgix, S3/R2 with CORS all are).
 * The frame loop only runs while the sphere is on screen and something is
 * moving; with reduced motion nothing moves by itself, nothing flings, and
 * every change is instant.
 * ───────────────────────────────────────────────────────────────────────── */

export interface ImageSphereItem {
  /** Image URL. The card keeps its shape, cropped only past tall portrait (0.62) or 16:9. */
  src: string;
  /** Describes the image for screen readers. */
  alt: string;
  /** A group's `id`. Items without one stay on the sphere. */
  group?: string;
}

export interface ImageSphereGroup {
  /** Unique id that items point at with their `group`. */
  id: string;
  /** The group's name: the tag beside the pointer on hover, and its keyboard button. */
  label: string;
}

export interface ImageSphereProps extends Omit<
  ComponentProps<"section">,
  "children"
> {
  /** Your images. Each can belong to a group, which gathers into a pile. */
  items?: ImageSphereItem[];
  /** The groups items belong to, by id, with the label shown on hover. */
  groups?: ImageSphereGroup[];
  /**
   * Cards on the sphere; items repeat round it to fill them. Defaults to
   * 240, or 140 on screens narrower than 40rem. Never fewer than items.
   */
  count?: number;
  /** Turns slowly while nobody's using it and no group is open. */
  autoRotate?: boolean;
  /** The group open at first, by id. */
  defaultGroup?: string | null;
  /**
   * The open group, when the parent decides it (e.g. from scroll). Clicks
   * then only report through `onGroupChange`, and the block's own
   * keyboard buttons are left out: the parent's controls take their place.
   */
  group?: string | null;
  /** Called when a group opens (its id) or closes (null). */
  onGroupChange?: (group: string | null) => void;
  /** The keyboard button that closes the open group. */
  allLabel?: string;
  /** The line in the top corner, until the first touch. Pass null to hide it. */
  hint?: ReactNode;
  /** Seconds the globe takes for one full turn when idle. Defaults to 45. */
  turnDuration?: number;
  /** Most images a group's pile shows. Defaults to 12. */
  pileSize?: number;
  /**
   * How curved the pile's images are, from 0 (flat) to 1 (most curved).
   * Defaults to 0.6.
   */
  pileCurve?: number;
}

/** A pile curve of 0–1 as the radius its cards are bent round (globe radii). */
const bendFor = (curve: number) =>
  curve <= 0.01 ? 1000 : 0.45 / Math.min(curve, 1);

/** The props that tune the scene, applied to it as they change. */
const applySettings = (
  scene: SphereScene,
  settings: {
    autoRotate: boolean;
    pileCurve: number;
    pileSize: number;
    turnDuration: number;
  }
) => {
  scene.autoRotate = settings.autoRotate;
  scene.idleSpin = (2 * Math.PI) / Math.max(settings.turnDuration, 1);
  scene.pileMax = Math.max(Math.round(settings.pileSize), 1);
  scene.pileBend = bendFor(settings.pileCurve);
};

/** Pixels a press can wander before it becomes a drag. */
const TAP_SLOP = 6;
/** A release this long after the last move is a stop, not a fling. */
const FLING_WINDOW = 80;

